import Foundation
import Metal

/// Grades interpolation quality using the original video as ground truth.
///
/// * `evaluate`: compare any interpolated file (made by Lumora or another app, even if HDR was added or the
///   picture was regraded) against its original. Originals the interpolated file should have kept are compared
///   directly; generated frames are checked against the two real frames around them.
/// * `benchmark`: the strictest test. Real frames are removed from the original, regenerated by every installed
///   model, and scored against the frames that were actually there. Also calibrates the artifact detector.
enum InterpolationEvaluator {
    struct Flagged: Hashable, Identifiable {
        var id: Int { outputIndex }
        var outputIndex: Int
        var seconds: Double
        var reason: String
    }

    struct Report {
        var offsetSeconds: Double
        var rateRatio: Double
        var toneMatched: Bool
        var originalsPSNR: Float           // how faithfully the original frames survive (dB, PQ domain)
        var originalsSSIM: Float
        var generatedChecked: Int
        var artifactRate: Float            // share of generated frames with structure in neither neighbour
        var ghostingRate: Float            // generated frames that are only cross-fades
        var duplicateRate: Float           // generated frames that are copies (not real interpolation)
        var cutMorphs: Int                 // frames that morph between two different shots
        var smoothness: Float              // 0...100, even motion steps between originals
        var score: Int
        var verdict: String
        var findings: [String]
        var flagged: [Flagged]
    }

    struct ModelScore: Hashable, Identifiable {
        var id: String { name }
        var name: String
        var psnr: Float
        var ssim: Float
        var flaggedFrames: Int
        var msPerFrame: Double
    }

    struct Benchmark {
        var samples: Int
        var scores: [ModelScore]
        var recommendedModel: String?
        var recommendedSensitivity: Float
        var summary: String
    }

    static let width = 960

    // MARK: Original vs interpolated file

    static func evaluate(original a: SourceDescriptor, originalColor ca: SourceColor, analysis: AnalysisResult?,
                         interpolated b: SourceDescriptor, interpolatedColor cb: SourceColor, fullScan: Bool = false,
                         progress: @escaping (Double) -> Void) async throws -> Report {
        let r = GradeRenderer()
        let qc = InterpolationQC()
        let srcA = try await a.makeFrameSource(), srcB = try await b.makeFrameSource()
        let ratio = b.fps / a.fps

        // 1. Time alignment (files can start a few frames apart).
        let uA = UniformBuilder.analysis(source: ca, gridW: 320, gridH: 180), uB = UniformBuilder.analysis(source: cb, gridW: 320, gridH: 180)
        var offsets: [Double] = []
        for f in [0.3, 0.5, 0.7] {
            let t = a.durationSeconds * f
            try srcA.start(at: Int(t * a.fps), count: 1)
            guard let fa = try srcA.nextFrame() else { continue }
            let ta = zscore(r.analyze(fa.texture, uniforms: uA, gridWidth: 320).thumbnail)
            let w = Int(b.fps)
            let start = max(0, Int(t * b.fps) - w)
            try srcB.start(at: start, count: 2 * w)
            var best = (score: -Float.infinity, frame: start), j = start
            while let fb = try srcB.nextFrame() {
                let s = zip(ta, zscore(r.analyze(fb.texture, uniforms: uB, gridWidth: 320).thumbnail)).reduce(0) { $0 + $1.0 * $1.1 }
                if s > best.score { best = (s, j) }
                j += 1
            }
            offsets.append(Double(best.frame) / b.fps - t)
        }
        let offset = offsets.isEmpty ? 0 : offsets.sorted()[offsets.count / 2]

        // Sample intervals [i, i+1] of the original across the whole film.
        // Full scan checks every gap between original frames (needed before a repair); otherwise ~60 samples.
        let samples = fullScan ? max(2, a.frameCount - 1) : min(60, max(4, a.frameCount / 48))
        let intervals = fullScan ? Array(0..<(a.frameCount - 1))
            : (0..<samples).map { k in Int(Double(a.frameCount - 2) * (0.03 + 0.94 * Double(k) / Double(samples - 1))) }

        func bFrames(for i: Int) -> [(index: Int, t: Double)] {
            let t0 = Double(i) / a.fps + offset, t1 = Double(i + 1) / a.fps + offset
            let j0 = Int((t0 * b.fps - 0.01).rounded(.up)), j1 = Int((t1 * b.fps + 0.01).rounded(.down))
            return (j0...max(j0, j1)).map { ($0, ((Double($0) / b.fps) - t0) / (t1 - t0)) }.filter { $0.index >= 0 }
        }

        // 2. Tone normalisation: if the interpolated version was regraded (e.g. HDR added), fit a curve from
        //    original to interpolated on the aligned original frames, so we compare motion, not grading.
        var hA = [Double](repeating: 0, count: 256), hB = hA
        for i in intervals.prefix(12) {
            guard let aligned = bFrames(for: i).first(where: { $0.t < 0.02 }) else { continue }
            try srcA.start(at: i, count: 1); try srcB.start(at: aligned.index, count: 1)
            guard let fa = try srcA.nextFrame(), let fb = try srcB.nextFrame() else { continue }
            for (k, c) in r.pqHistogram(r.comparable(fa.texture, color: ca, width: width)).enumerated() { hA[k] += Double(c) }
            for (k, c) in r.pqHistogram(r.comparable(fb.texture, color: cb, width: width)).enumerated() { hB[k] += Double(c) }
        }
        let curve = cdfMatch(hA, hB)
        let toneMatched = zip(curve, (0..<256).map { Float($0) / 255 }).contains { abs($0 - $1) > 0.02 }
        progress(0.15)

        // 3. Measure every sampled interval.
        var psnrs: [Float] = [], ssims: [Float] = []
        var generated = 0, artifacts = 0, ghosts = 0, dupes = 0, morphs = 0
        var smoothness: [Float] = []
        var flagged: [Flagged] = []
        for (n, i) in intervals.enumerated() {
            try Task.checkCancellation()
            let frames = bFrames(for: i)
            guard let first = frames.first, let last = frames.last else { continue }
            try srcA.start(at: i, count: 2)
            guard let a0 = try srcA.nextFrame(), let a1 = try srcA.nextFrame() else { continue }
            let A0 = r.toneMatch(r.comparable(a0.texture, color: ca, width: width), curve: curve)
            let A1 = r.toneMatch(r.comparable(a1.texture, color: ca, width: width), curve: curve)
            let isCut = analysis?.cutFrames.contains(i + 1) ?? false
            try srcB.start(at: first.index, count: last.index - first.index + 1)
            var steps: [Float] = []
            var previous = A0
            for f in frames {
                guard let fb = try srcB.nextFrame() else { break }
                let B = r.comparable(fb.texture, color: cb, width: width)
                if f.t < 0.02 || f.t > 0.98 {
                    let (p, s) = r.compare(f.t < 0.5 ? A0 : A1, B)
                    psnrs.append(p); ssims.append(s)
                } else {
                    generated += 1
                    let e = r.blendErrors(A0, A1, B, t: Float(f.t))
                    let (fraction, _) = qc.score(a: A0, b: A1, mid: B, sensitivity: 0.5)
                    let seconds = Double(f.index) / b.fps
                    if isCut && e.vsNearest > 0.01 {
                        morphs += 1; flagged.append(Flagged(outputIndex: f.index, seconds: seconds, reason: "Morphs between two different shots"))
                    } else if e.motion > 0.01 && e.vsNearest < e.motion * 0.08 {
                        dupes += 1; flagged.append(Flagged(outputIndex: f.index, seconds: seconds, reason: "Copy of a real frame (no new motion)"))
                    } else if e.motion > 0.01 && e.vsBlend < e.motion * 0.12 {
                        ghosts += 1; flagged.append(Flagged(outputIndex: f.index, seconds: seconds, reason: "Cross-fade: ghosting instead of motion"))
                    } else if fraction > 0.02 {
                        artifacts += 1
                        flagged.append(Flagged(outputIndex: f.index, seconds: seconds,
                                               reason: "Warping / tearing in \(Int(fraction * 100))% of the frame"))
                    }
                }
                steps.append(r.blendErrors(previous, B, B, t: 0).motion)
                previous = B
            }
            steps.append(r.blendErrors(previous, A1, A1, t: 0).motion)
            let mean = steps.reduce(0, +) / Float(max(1, steps.count))
            if steps.count > 2, mean > 0.004, !isCut {
                let sd = sqrtf(steps.reduce(0) { $0 + ($1 - mean) * ($1 - mean) } / Float(steps.count))
                smoothness.append(100 * max(0, 1 - sd / mean))
            }
            progress(0.15 + 0.85 * Double(n + 1) / Double(intervals.count))
        }
        srcA.cancel(); srcB.cancel()

        let g = Float(max(1, generated))
        let artifactRate = Float(artifacts) / g, ghostRate = Float(ghosts) / g, dupeRate = Float(dupes) / g
        let smooth = smoothness.isEmpty ? 100 : smoothness.reduce(0, +) / Float(smoothness.count)
        let psnr = psnrs.isEmpty ? 0 : psnrs.reduce(0, +) / Float(psnrs.count)
        let ssim = ssims.isEmpty ? 0 : ssims.reduce(0, +) / Float(ssims.count)
        var score: Float = 100 - artifactRate * 120 - ghostRate * 60 - dupeRate * 80 - Float(morphs) * 4 - (100 - smooth) * 0.25
        if !psnrs.isEmpty && psnr < 38 { score -= (38 - psnr) * 1.5 }
        let s = Int(max(0, min(100, score)))

        var findings: [String] = []
        if generated == 0 { findings.append("No in-between frames found: the frame rate didn't change, or the files don't line up.") }
        findings.append(psnrs.isEmpty ? "Couldn't line up any original frames."
            : String(format: "Original frames kept at %.1f dB / SSIM %.3f%@.", psnr, ssim,
                     psnr > 45 ? " — essentially untouched" : psnr > 38 ? " — light re-encode loss" : " — noticeably altered"))
        if toneMatched { findings.append("The interpolated file was regraded (e.g. HDR added); differences in grading were factored out.") }
        findings.append(String(format: "%.1f%% of generated frames show warping or tearing.", artifactRate * 100))
        if ghostRate > 0.02 { findings.append(String(format: "%.0f%% of generated frames are plain cross-fades (ghosting).", ghostRate * 100)) }
        if dupeRate > 0.02 { findings.append(String(format: "%.0f%% of \"new\" frames are just copies — fake smoothness.", dupeRate * 100)) }
        if morphs > 0 { findings.append("\(morphs) frames morph across scene cuts.") }
        findings.append(String(format: "Motion smoothness %.0f/100.", smooth))
        let verdict = s >= 90 ? "Excellent interpolation" : s >= 75 ? "Good, with a few problem spots"
                    : s >= 55 ? "Noticeable artifacts" : "Poor interpolation"
        return Report(offsetSeconds: offset, rateRatio: ratio, toneMatched: toneMatched, originalsPSNR: psnr,
                      originalsSSIM: ssim, generatedChecked: generated, artifactRate: artifactRate,
                      ghostingRate: ghostRate, duplicateRate: dupeRate, cutMorphs: morphs, smoothness: smooth,
                      score: s, verdict: verdict, findings: findings, flagged: flagged)
    }

    // MARK: Hold-out benchmark on the original

    static func benchmark(original a: SourceDescriptor, color: SourceColor, analysis: AnalysisResult,
                          progress: @escaping (Double) -> Void) async throws -> Benchmark {
        guard a.frameCount > 8 else { throw LumoraError.unsupported("The clip is too short to benchmark.") }
        let r = GradeRenderer()
        let qc = InterpolationQC()
        let src = try await a.makeFrameSource()
        let proxy = UniformBuilder.analysis(source: color, gridW: 1, gridH: 1)
        var engines: [InterpolationEngine] = [BlendInterpolator()]
        for spec in InterpolationModelSpec.all() where spec.isInstalled {
            if let e = try? CoreMLInterpolator(spec: spec, proxyUniforms: proxy) { engines.append(e) }
        }
        // Triplets (i-1, i, i+1) inside one shot, away from cuts, fades and repeated frames.
        let candidates = (2..<(a.frameCount - 2)).filter { i in
            !analysis.cutFrames.contains(i) && !analysis.cutFrames.contains(i + 1)
                && analysis.transition(containing: i) == nil && !analysis.duplicateFrames.contains(i)
        }
        let n = min(24, candidates.count)
        guard n > 0 else { throw LumoraError.unsupported("No usable stretches of motion found for a benchmark.") }
        let picks = (0..<n).map { candidates[$0 * candidates.count / n] }

        var acc: [String: (psnr: Float, ssim: Float, flagged: Int, ms: Double)] = [:]
        var realScores: [[Float]] = [[], [], [], [], []]       // QC fractions on *real* frames at 5 sensitivities
        let sensitivities: [Float] = [0, 0.25, 0.5, 0.75, 1]
        for (k, i) in picks.enumerated() {
            try Task.checkCancellation()
            try src.start(at: i - 1, count: 3)
            guard let f0 = try src.nextFrame(), let truth = try src.nextFrame(), let f2 = try src.nextFrame() else { continue }
            let T = r.comparable(truth.texture, color: color, width: width)
            let C0 = r.comparable(f0.texture, color: color, width: width), C2 = r.comparable(f2.texture, color: color, width: width)
            for (si, s) in sensitivities.enumerated() { realScores[si].append(qc.score(a: C0, b: C2, mid: T, sensitivity: s).fraction) }
            for e in engines {
                let out = MetalContext.shared.makeTexture(width: f0.texture.width, height: f0.texture.height,
                                                          format: f0.texture.pixelFormat)
                let start = Date()
                _ = try e.interpolate(f0.texture, f2.texture, times: [0.5], into: [out], qcTiles: (1, 1))
                let ms = Date().timeIntervalSince(start) * 1000
                let G = r.comparable(out, color: color, width: width)
                let (p, s) = r.compare(T, G)
                let flagged = qc.score(a: C0, b: C2, mid: G, sensitivity: 0.5).fraction > 0 ? 1 : 0
                let prev = acc[e.name] ?? (0, 0, 0, 0)
                acc[e.name] = (prev.psnr + p, prev.ssim + s, prev.flagged + flagged, prev.ms + ms)
            }
            progress(Double(k + 1) / Double(n))
        }
        src.cancel()
        let scores = acc.map { ModelScore(name: $0.key, psnr: $0.value.psnr / Float(n), ssim: $0.value.ssim / Float(n),
                                          flaggedFrames: $0.value.flagged, msPerFrame: $0.value.ms / Double(n)) }
            .sorted { ($0.ssim, $0.psnr) > ($1.ssim, $1.psnr) }
        // Strictest setting that flags (almost) no real frames: few false alarms, maximum sensitivity.
        var recommended: Float = 0
        for (si, s) in sensitivities.enumerated() {
            let fp = Float(realScores[si].filter { $0 > 0 }.count) / Float(max(1, realScores[si].count))
            if fp <= 0.02 { recommended = s }
        }
        let best = scores.first { $0.name != "Blend" }
        let summary: String
        if let best, let blend = scores.first(where: { $0.name == "Blend" }) {
            summary = String(format: "%@ rebuilt the removed frames best (%.1f dB, SSIM %.3f) — %.1f dB better than a plain cross-fade. Artifact detector strictness set to %.2f.",
                             best.name, best.psnr, best.ssim, best.psnr - blend.psnr, recommended)
        } else {
            summary = "Install an interpolation model to compare it against plain blending."
        }
        return Benchmark(samples: n, scores: scores, recommendedModel: best?.name,
                         recommendedSensitivity: recommended, summary: summary)
    }

    // MARK: Helpers

    /// Monotonic 256-entry curve mapping histogram A onto histogram B (values 0...1).
    static func cdfMatch(_ a: [Double], _ b: [Double]) -> [Float] {
        let ta = a.reduce(0, +), tb = b.reduce(0, +)
        guard ta > 0, tb > 0 else { return (0..<256).map { Float($0) / 255 } }
        var cb: [Double] = [], run = 0.0
        for v in b { run += v; cb.append(run / tb) }
        var curve: [Float] = [], ca = 0.0, j = 0
        for v in a {
            ca += v
            let q = ca / ta
            while j < 255 && cb[j] < q { j += 1 }
            curve.append(Float(j) / 255)
        }
        for k in 1..<curve.count { curve[k] = max(curve[k], curve[k - 1]) }
        return curve
    }

    static func zscore(_ v: [Float]) -> [Float] {
        let n = Float(max(1, v.count)), mean = v.reduce(0, +) / n
        let sd = max(1e-5, sqrtf(v.reduce(0) { $0 + ($1 - mean) * ($1 - mean) } / n))
        return v.map { ($0 - mean) / sd / n }
    }
}
